using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace Underwater.Editor {
public static class ReefRealismPass {
 public static void Run(){Apply();ReefCreaturePolish.Validate();Validate();}
 const string Scene="Assets/Scenes/Underwater_Realistic.unity",Folder="Assets/UnderwaterArt/RealismPass";
 public static void Audit(){EditorSceneManager.OpenScene(Scene);var seen=new HashSet<Mesh>();foreach(var filter in UnityEngine.Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None))if(filter.GetComponent<FishAgent>()||filter.GetComponent<FishBodyMotion>()){if(!seen.Add(filter.sharedMesh))continue;var b=BoundsOf(filter.sharedMesh.vertices);Debug.Log("EYE_AUDIT_FISH "+filter.name+" mesh="+filter.sharedMesh.name+" bounds="+b);}
  foreach(var turtle in UnityEngine.Object.FindObjectsByType<TurtleSwimmer>(FindObjectsSortMode.None))foreach(var filter in turtle.GetComponentsInChildren<MeshFilter>())Debug.Log("EYE_AUDIT_TURTLE "+filter.name+" bounds="+BoundsOf(filter.sharedMesh.vertices)+" material="+filter.GetComponent<Renderer>().sharedMaterial.name+" enabled="+filter.GetComponent<Renderer>().enabled);
 }
 static Bounds BoundsOf(Vector3[] vertices){var b=new Bounds(vertices[0],Vector3.zero);foreach(var v in vertices)b.Encapsulate(v);return b;}
 public static void Apply(){var scene=EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();RealisticGrouper();SmoothOctopus();RefineRays();RefineMoray();FitFishEyes();FitTurtleEyes();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Validate();Capture();}
 static Mesh Save(Mesh mesh,string name){string path=Folder+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.indexFormat=mesh.indexFormat;old.vertices=mesh.vertices;old.triangles=mesh.triangles;old.normals=mesh.normals;old.uv=mesh.uv;old.uv2=mesh.uv2;old.colors=mesh.colors;old.tangents=mesh.tangents;old.boneWeights=mesh.boneWeights;old.bindposes=mesh.bindposes;old.bounds=mesh.bounds;old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static Material Material(string name,string shader,Color color){string path=Folder+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find(shader));AssetDatabase.CreateAsset(m,path);}m.shader=Shader.Find(shader);m.color=color;EditorUtility.SetDirty(m);return m;}
 static void RealisticGrouper(){foreach(var actor in UnityEngine.Object.FindObjectsByType<WreckCreature>(FindObjectsSortMode.None))if(actor.species==WreckCreature.Species.Grouper){var mesh=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<Mesh>("Assets/UnderwaterArt/Meshes/PhotographicFishCanonical.asset"));var vertices=mesh.vertices;for(int i=0;i<vertices.Length;i++){var p=vertices[i];p.x*=1.55f;p.y*=1.18f;p.z*=1.2f;vertices[i]=p;}mesh.vertices=vertices;mesh.RecalculateNormals();mesh.RecalculateBounds();mesh.RecalculateTangents();actor.GetComponent<MeshFilter>().sharedMesh=Save(mesh,"DetailedGrouperBody");var m=Material("Natural mottled grouper","Underwater/Living Fish Skin",new Color(.58f,.54f,.39f));m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/UnderwaterArt/Textures/FishScan_albedo.png");m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/UnderwaterArt/Textures/FishScan_normal.png"));m.SetFloat("_Grouper",1);actor.GetComponent<Renderer>().sharedMaterial=m;}}
 static Vector3 Surface(Mesh mesh,int side,float y,float z){var temp=new GameObject("Temporary eye fitting"){hideFlags=HideFlags.HideAndDontSave};var collider=temp.AddComponent<MeshCollider>();collider.sharedMesh=mesh;Vector3 p;var ray=new Ray(new Vector3(side*10,y,z),Vector3.left*side);if(collider.Raycast(ray,out var hit,20))p=hit.point;else throw new Exception("Cannot fit eye to head "+mesh.name+" y="+y+" z="+z);UnityEngine.Object.DestroyImmediate(temp);return p;}
 static Mesh WithEyes(Mesh source,float y,float z,float radius,float pupilHeight=1){var iris=new ReefGeometry();var pupil=new ReefGeometry();for(int side=-1;side<=1;side+=2){Vector3 p=Surface(source,side,y,z);iris.Ellipsoid(p+Vector3.right*side*.003f,new Vector3(radius*.42f,radius,radius),5,10);pupil.Ellipsoid(p+Vector3.right*side*(radius*.42f+.004f),new Vector3(radius*.14f,radius*.66f*pupilHeight,radius*.66f),5,10);}
  var im=iris.Mesh("Fitted irises");var pm=pupil.Mesh("Fitted pupils");var original=UnityEngine.Object.Instantiate(source);original.uv2=new Vector2[original.vertexCount];im.uv2=Tag(im.vertexCount,1);pm.uv2=Tag(pm.vertexCount,2);var mesh=new Mesh{name=source.name+" with fitted anatomical eyes",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.CombineMeshes(new[]{new CombineInstance{mesh=original,transform=Matrix4x4.identity},new CombineInstance{mesh=im,transform=Matrix4x4.identity},new CombineInstance{mesh=pm,transform=Matrix4x4.identity}},true,true);mesh.RecalculateTangents();var bounds=source.bounds;bounds.Encapsulate(mesh.bounds);mesh.bounds=bounds;UnityEngine.Object.DestroyImmediate(original);UnityEngine.Object.DestroyImmediate(im);UnityEngine.Object.DestroyImmediate(pm);return mesh;
 }
 static Vector2[] Tag(int n,float tag){var uv=new Vector2[n];for(int i=0;i<n;i++)uv[i]=new Vector2(tag,0);return uv;}
 static Mesh AddSuckers(Mesh source){var temp=new GameObject("Temporary arm fitting"){hideFlags=HideFlags.HideAndDontSave};var collider=temp.AddComponent<MeshCollider>();collider.sharedMesh=source;var rims=new ReefGeometry();int count=0;for(int arm=0;arm<8;arm++)for(int station=0;station<12;station++)for(int row=-1;row<=1;row+=2){float angle=arm*Mathf.PI/4+.16f;float radius=.36f+station*.055f;var radial=new Vector3(Mathf.Sin(angle),0,Mathf.Cos(angle));var tangent=new Vector3(radial.z,0,-radial.x);var position=radial*radius+tangent*row*.025f;if(!collider.Raycast(new Ray(position+Vector3.down,Vector3.up),out var hit,1.3f)||hit.point.y>.28f||hit.normal.y>-.1f)continue;var n=hit.normal;var u=Vector3.Cross(n,Vector3.right).normalized;if(u.sqrMagnitude<.1f)u=Vector3.Cross(n,Vector3.forward).normalized;var w=Vector3.Cross(n,u);var points=new Vector3[13];var widths=new float[13];float cupRadius=Mathf.Lerp(.025f,.014f,station/11f);for(int i=0;i<13;i++){float a=i*Mathf.PI*2/12;points[i]=hit.point+n*.001f+(u*Mathf.Cos(a)+w*Mathf.Sin(a))*cupRadius;widths[i]=.004f;}rims.Tube(points,widths,5,Color.white);count++;}UnityEngine.Object.DestroyImmediate(temp);if(count==0)throw new Exception("Octopus sucker fitting found no arm surface");var cups=rims.Mesh("Surface fitted sucker rings");cups.uv2=Tag(cups.vertexCount,3);var mesh=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32,name="Detailed octopus with physical suckers"};mesh.CombineMeshes(new[]{new CombineInstance{mesh=source,transform=Matrix4x4.identity},new CombineInstance{mesh=cups,transform=Matrix4x4.identity}},true,true);mesh.bounds=source.bounds;UnityEngine.Object.DestroyImmediate(cups);Debug.Log("OCTOPUS_SUCKERS count="+count);return mesh;}
 static void RefineMoray(){foreach(var actor in UnityEngine.Object.FindObjectsByType<WreckCreature>(FindObjectsSortMode.None))if(actor.species==WreckCreature.Species.Moray){var mat=Material("Mottled moray skin","Underwater/Wreck Creature Skin",new Color(.31f,.32f,.16f));mat.SetFloat("_Kind",1);actor.GetComponent<Renderer>().sharedMaterial=mat;var jaw=actor.jaw.GetComponentInChildren<Renderer>();if(jaw)jaw.sharedMaterial=mat;var teeth=Material("Moray tooth enamel","Standard",new Color(.58f,.55f,.40f));teeth.SetFloat("_Glossiness",.32f);for(int lower=0;lower<2;lower++){var parent=lower==0?actor.transform:actor.jaw;var old=parent.Find("Small curved teeth");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var g=new ReefGeometry();for(int side=-1;side<=1;side+=2)for(int i=0;i<5;i++){float z=(lower==0?.43f:.06f)+i*.045f;float x=side*Mathf.Lerp(.105f,.065f,i/4f),y=lower==0?.025f:.007f;float sign=lower==0?-1:1;g.Tube(new[]{new Vector3(x,y,z),new Vector3(x*.96f,y+sign*.022f,z+.005f),new Vector3(x*.9f,y+sign*.037f,z+.01f)},new[]{.005f,.003f,.0004f},6,Color.white);}var child=new GameObject("Small curved teeth");child.transform.SetParent(parent,false);child.AddComponent<MeshFilter>().sharedMesh=Save(g.Mesh("Moray tooth rows"),"MorayTeeth"+lower);child.AddComponent<MeshRenderer>().sharedMaterial=teeth;}}}
 static void FitFishEyes(){var cache=new Dictionary<Mesh,Mesh>();int count=0;foreach(var filter in UnityEngine.Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None)){if(!filter.GetComponent<FishAgent>()&&!filter.GetComponent<FishBodyMotion>()&&!(filter.GetComponent<WreckCreature>()&&filter.GetComponent<WreckCreature>().species==WreckCreature.Species.Grouper))continue;var renderer=filter.GetComponent<Renderer>();if(!renderer||renderer.sharedMaterial.shader.name!="Underwater/Living Fish Skin")continue;var source=filter.sharedMesh;if(!cache.TryGetValue(source,out var result)){// Start with source anatomy on repeat runs, rather than appending a second pair.
    string path=AssetDatabase.GetAssetPath(source);if(path.StartsWith(Folder+"/Eyes_")){result=source;}else{var b=BoundsOf(source.vertices);float y=b.center.y-.025f*(b.size.y/.44f),z=b.max.z-b.size.z*.065f;var eye=WithEyes(source,y,z,b.size.z*.014f);result=Save(eye,"Eyes_"+AssetDatabase.AssetPathToGUID(path).Substring(0,12));}cache[source]=result;}
   filter.sharedMesh=result;count++;
  }Debug.Log("FITTED_FISH_EYES animals="+count+" uniqueMeshes="+cache.Count);
 }
 static void FitTurtleEyes(){int count=0;foreach(var turtle in UnityEngine.Object.FindObjectsByType<TurtleSwimmer>(FindObjectsSortMode.None)){MeshFilter skin=null;foreach(var filter in turtle.GetComponentsInChildren<MeshFilter>())if(filter.name.StartsWith("Continuous anatomical"))skin=filter;if(!skin)throw new Exception("Turtle skin missing");var old=turtle.transform.Find("Surface fitted iris and pupil");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);foreach(var renderer in turtle.GetComponentsInChildren<Renderer>())if(renderer.name.Contains("iris")||renderer.name.Contains("pupil"))renderer.enabled=false;
   var iris=new ReefGeometry();var pupils=new ReefGeometry();for(int side=-1;side<=1;side+=2){var p=Surface(skin.sharedMesh,side,.012f,.65f);iris.Ellipsoid(p+Vector3.right*side*.004f,new Vector3(.008f,.018f,.018f),8,12);pupils.Ellipsoid(p+Vector3.right*side*.012f,new Vector3(.003f,.011f,.011f),8,12);Debug.Log("TURTLE_EYE_SURFACE "+side+" "+p);}var a=iris.Mesh("Turtle iris");a.uv2=Tag(a.vertexCount,1);var b=pupils.Mesh("Turtle pupils");b.uv2=Tag(b.vertexCount,2);var combined=new Mesh();combined.CombineMeshes(new[]{new CombineInstance{mesh=a,transform=Matrix4x4.identity},new CombineInstance{mesh=b,transform=Matrix4x4.identity}},true,true);var mesh=Save(combined,"SurfaceFittedTurtleEyes");var eye=new GameObject("Surface fitted iris and pupil");eye.transform.SetParent(turtle.transform,false);eye.AddComponent<MeshFilter>().sharedMesh=mesh;eye.AddComponent<MeshRenderer>().sharedMaterial=Material("Turtle eyes","Underwater/Loggerhead Skin",Color.white);count++;UnityEngine.Object.DestroyImmediate(a);UnityEngine.Object.DestroyImmediate(b);
  }Debug.Log("FITTED_TURTLE_EYES turtles="+count);
 }
 static Vector3Int Key(Vector3 p)=>new Vector3Int(Mathf.RoundToInt(p.x*10000),Mathf.RoundToInt(p.y*10000),Mathf.RoundToInt(p.z*10000));
 static void SmoothNormals(Mesh mesh){var normals=mesh.normals;var v=mesh.vertices;var sums=new Dictionary<Vector3Int,Vector3>();for(int i=0;i<v.Length;i++){var k=Key(v[i]);sums.TryGetValue(k,out var n);sums[k]=n+normals[i];}for(int i=0;i<v.Length;i++)normals[i]=sums[Key(v[i])].normalized;mesh.normals=normals;}
 static Mesh Subdivide(Mesh source){var v=new List<Vector3>(source.vertices);var uv=new List<Vector2>(source.uv);if(uv.Count!=v.Count)for(int i=uv.Count;i<v.Count;i++)uv.Add(Vector2.zero);var edges=new Dictionary<ulong,int>();int Mid(int a,int b){uint low=(uint)Mathf.Min(a,b),high=(uint)Mathf.Max(a,b);ulong key=((ulong)low<<32)|high;if(edges.TryGetValue(key,out int found))return found;int n=v.Count;v.Add((v[a]+v[b])*.5f);uv.Add((uv[a]+uv[b])*.5f);edges[key]=n;return n;}var triangles=new List<int>();var t=source.triangles;for(int i=0;i<t.Length;i+=3){int a=t[i],b=t[i+1],c=t[i+2],ab=Mid(a,b),bc=Mid(b,c),ca=Mid(c,a);triangles.AddRange(new[]{a,ab,ca,ab,b,bc,ca,bc,c,ab,bc,ca});}
  // Relax a welded neighbourhood slightly, retaining small sucker rims and arm curls.
  var sums=new Dictionary<Vector3Int,Vector3>();var counts=new Dictionary<Vector3Int,int>();for(int i=0;i<triangles.Count;i+=3)for(int j=0;j<3;j++){int a=triangles[i+j],b=triangles[i+(j+1)%3];var k=Key(v[a]);sums.TryGetValue(k,out var sum);counts.TryGetValue(k,out int n);sums[k]=sum+v[b];counts[k]=n+1;}var positions=v.ToArray();for(int i=0;i<positions.Length;i++){var key=Key(v[i]);positions[i]=Vector3.Lerp(v[i],(counts.ContainsKey(key)?sums[key]/counts[key]:v[i]),.3f);}var mesh=new Mesh{name="Smooth detailed octopus",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.vertices=positions;mesh.uv=uv.ToArray();mesh.triangles=triangles.ToArray();mesh.RecalculateNormals();SmoothNormals(mesh);mesh.RecalculateTangents();mesh.RecalculateBounds();var bounds=mesh.bounds;bounds.Expand(.15f);mesh.bounds=bounds;return mesh;
 }
 static void SmoothOctopus(){foreach(var encounter in UnityEngine.Object.FindObjectsByType<ReefEncounter>(FindObjectsSortMode.None))if(encounter.response==ReefEncounter.Response.Octopus){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/UnderwaterArt/LicensedOctopus/Octopus.fbx");var temp=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var parts=temp.GetComponentsInChildren<MeshFilter>();var combine=new CombineInstance[parts.Length];for(int i=0;i<parts.Length;i++)combine[i]=new CombineInstance{mesh=parts[i].sharedMesh,transform=parts[i].transform.localToWorldMatrix};var source=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};source.CombineMeshes(combine,true,true);UnityEngine.Object.DestroyImmediate(temp);Debug.Log("OCTOPUS_CANONICAL "+BoundsOf(source.vertices));var subdivided=Subdivide(source);var eyes=WithEyes(subdivided,.50f,-.15f,.042f,.35f);var detailed=AddSuckers(eyes);var smooth=Save(detailed,"SmoothOctopus");var old=encounter.transform.Find("Detailed octopus");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var model=new GameObject("Detailed octopus");model.transform.SetParent(encounter.transform,false);model.transform.localScale=Vector3.one*.5f;model.transform.localPosition=Vector3.down*.085f;model.AddComponent<MeshFilter>().sharedMesh=smooth;var mat=Material("Natural octopus skin","Underwater/Octopus Skin",new Color(.45f,.29f,.19f));model.AddComponent<MeshRenderer>().sharedMaterial=mat;encounter.skin=model.GetComponentsInChildren<Renderer>();foreach(var mesh in new[]{source,subdivided,eyes})UnityEngine.Object.DestroyImmediate(mesh);Debug.Log("REALISTIC_OCTOPUS triangles="+smooth.triangles.Length/3);}}
 static void RefineRays(){var g=new ReefGeometry();const int rings=24,sides=96;for(int surface=0;surface<2;surface++)for(int r=0;r<=rings;r++)for(int a=0;a<=sides;a++){float radius=r/(float)rings,theta=a*Mathf.PI*2/sides;float x=Mathf.Sin(theta)*radius*.96f,z=Mathf.Cos(theta)*radius*(Mathf.Cos(theta)>0?.64f:.54f);float mantle=Mathf.Exp(-x*x/ .052f-z*z/.24f);float y=surface==0?.015f+.14f*mantle*(1-radius*radius):-.035f*(1-radius*radius);g.Vertex(new Vector3(x,y,z),new Vector2(x*.5f+.5f,z*.6f+.5f),Color.white);}int layer=(rings+1)*(sides+1);for(int surface=0;surface<2;surface++)for(int r=0;r<rings;r++)for(int a=0;a<sides;a++){int i=surface*layer+r*(sides+1)+a;if(surface==0)g.Quad(i,i+sides+1,i+sides+2,i+1);else g.Quad(i,i+1,i+sides+2,i+sides+1);}for(int a=0;a<sides;a++){int i=rings*(sides+1)+a;g.Quad(i,i+1,layer+i+1,layer+i);}var tail=new Vector3[29];var widths=new float[29];for(int i=0;i<tail.Length;i++){float t=i/28f;tail[i]=new Vector3(Mathf.Sin(t*2)*.06f,0,Mathf.Lerp(-.5f,-1.85f,t));widths[i]=Mathf.Lerp(.035f,.003f,t);}g.Tube(tail,widths,12,Color.white);var body=g.Mesh("Closed anatomical stingray with tapered tail");SmoothNormals(body);body.uv2=Tag(body.vertexCount,0);
  var irises=new ReefGeometry();var pupils=new ReefGeometry();var gills=new ReefGeometry();for(int side=-1;side<=1;side+=2){float x=side*.13f,z=.28f;float radial=Mathf.Sqrt(x*x/(.96f*.96f)+z*z/(.64f*.64f));float y=.015f+.14f*Mathf.Exp(-x*x/.052f-z*z/.24f)*(1-radial*radial);var p=new Vector3(x,y,z);irises.Ellipsoid(p+Vector3.up*.006f,new Vector3(.019f,.014f,.024f),8,12);pupils.Ellipsoid(p+Vector3.up*.018f,new Vector3(.011f,.004f,.016f),6,12);for(int i=0;i<5;i++){float zz=.20f-i*.055f;gills.Tube(new[]{new Vector3(side*.13f,-.035f,zz),new Vector3(side*.2f,-.035f,zz-.015f),new Vector3(side*.27f,-.032f,zz-.007f)},new[]{.002f,.004f,.001f},5,Color.white);}}
  var iris=irises.Mesh("Raised stingray eyes");iris.uv2=Tag(iris.vertexCount,1);var pupil=pupils.Mesh("Stingray pupils");pupil.uv2=Tag(pupil.vertexCount,2);var slits=gills.Mesh("Five paired gill slits");slits.uv2=Tag(slits.vertexCount,4);var combined=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32,name="Detailed animated stingray"};combined.CombineMeshes(new[]{new CombineInstance{mesh=body,transform=Matrix4x4.identity},new CombineInstance{mesh=iris,transform=Matrix4x4.identity},new CombineInstance{mesh=pupil,transform=Matrix4x4.identity},new CombineInstance{mesh=slits,transform=Matrix4x4.identity}},true,true);var b=combined.bounds;b.Expand(new Vector3(.15f,.6f,.15f));combined.bounds=b;var saved=Save(combined,"AnatomicalStingray");var material=Material("Detailed natural stingray","Underwater/Rigged Ray Skin",new Color(.28f,.27f,.21f));material.SetFloat("_ProceduralStroke",1);foreach(var ray in UnityEngine.Object.FindObjectsByType<StingraySwimmer>(FindObjectsSortMode.None)){foreach(string name in new[]{"Rigged stingray","Detailed ray mantle"}){var old=ray.transform.Find(name);if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);}ray.GetComponent<MeshFilter>().sharedMesh=saved;ray.GetComponent<MeshRenderer>().enabled=true;ray.GetComponent<MeshRenderer>().sharedMaterial=material;}foreach(var mesh in new[]{body,iris,pupil,slits})UnityEngine.Object.DestroyImmediate(mesh);Debug.Log("ANATOMICAL_RAYS triangles="+saved.triangles.Length/3+" closedDisc=true eyes=true gills=true");
 }
 public static void Validate(){EditorSceneManager.OpenScene(Scene);int fish=0,turtles=0;foreach(var f in UnityEngine.Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None)){bool animal=f.GetComponent<FishAgent>()||f.GetComponent<FishBodyMotion>()||(f.GetComponent<WreckCreature>()&&f.GetComponent<WreckCreature>().species==WreckCreature.Species.Grouper);if(!animal)continue;var tags=f.sharedMesh.uv2;int left=0,right=0;var vertices=f.sharedMesh.vertices;for(int i=0;i<tags.Length;i++)if(tags[i].x>1.5f){if(vertices[i].x<0)left++;else right++;}if(left<20||right<20)throw new Exception("Missing physical pupils: "+f.name);fish++;}
  foreach(var turtle in UnityEngine.Object.FindObjectsByType<TurtleSwimmer>(FindObjectsSortMode.None)){var eye=turtle.transform.Find("Surface fitted iris and pupil");if(!eye||!eye.GetComponent<Renderer>().enabled||eye.GetComponent<MeshFilter>().sharedMesh.uv2.Length==0)throw new Exception("Missing fitted turtle eyes");turtles++;}if(turtles!=2||fish<227)throw new Exception("Incomplete animal eye coverage");Debug.Log("REALISM_EYES_VALIDATED fish="+fish+" turtles="+turtles+" sides=both singleMaterialFishMeshes=true");
 }
 public static void Capture(){EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory("Renders/Realism");var camera=Camera.main;camera.fieldOfView=48;camera.nearClipPlane=.025f;camera.allowHDR=false;var atmosphere=UnityEngine.Object.FindFirstObjectByType<ReefAtmosphere>();var names=new HashSet<string>();foreach(var filter in UnityEngine.Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None))if(filter.GetComponent<FishAgent>()||filter.GetComponent<FishBodyMotion>()||(filter.GetComponent<WreckCreature>()&&filter.GetComponent<WreckCreature>().species==WreckCreature.Species.Grouper)){if(!names.Add(filter.name))continue;float size=BoundsOf(filter.sharedMesh.vertices).size.z*filter.transform.lossyScale.z;camera.transform.position=filter.transform.position+filter.transform.right*size*1.3f+filter.transform.forward*size*.25f+Vector3.up*size*.1f;camera.transform.LookAt(filter.transform.position);atmosphere.Apply(camera);ReefCorrectionAudit.Capture(camera,"Renders/Realism/Fish_"+filter.name.Replace(" ","_")+".png");}
  int turtleIndex=0;foreach(var turtle in UnityEngine.Object.FindObjectsByType<TurtleSwimmer>(FindObjectsSortMode.None)){for(int side=-1;side<=1;side+=2){camera.transform.position=turtle.transform.TransformPoint(new Vector3(side*.65f,.10f,1.1f));camera.transform.LookAt(turtle.transform.TransformPoint(new Vector3(0,.01f,.54f)));atmosphere.Apply(camera);ReefCorrectionAudit.Capture(camera,"Renders/Realism/Turtle_"+turtleIndex+"_"+side+".png");}turtleIndex++;}
  var octopus=Array.Find(UnityEngine.Object.FindObjectsByType<ReefEncounter>(FindObjectsSortMode.None),e=>e.response==ReefEncounter.Response.Octopus);camera.transform.position=octopus.transform.position+new Vector3(1,.65f,1);camera.transform.LookAt(octopus.transform.position+Vector3.up*.15f);atmosphere.Apply(camera);ReefCorrectionAudit.Capture(camera,"Renders/Realism/Octopus.png");var ray=UnityEngine.Object.FindFirstObjectByType<StingraySwimmer>();camera.transform.position=ray.transform.position+new Vector3(1.1f,1.1f,1.2f);camera.transform.LookAt(ray.transform.position+ray.transform.forward*-.3f);atmosphere.Apply(camera);ReefCorrectionAudit.Capture(camera,"Renders/Realism/Stingray.png");
 }
}
}
